418:export function boot(doc = document) {

  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember where the ball was before this move: brickHit sweeps the segment
  // between the two positions so a fast ball cannot tunnel through a brick.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Brick bounce (issue #1) ----------------------------------------------

// Penetrations closer than this (in px) are treated as equal: the ball hit a
// corner dead-on and both velocity components flip.
const FACE_EPS = 0.5;

// Continuous (swept) circle-vs-brick detection, slab method.
// The ball's centre sweeps from (px,py) along (dx,dy) over the frame; the test
// is the same segment against the brick rectangle expanded by the radius.
// Returns the earliest t in [0,1] at which the ball *enters* the brick this
// frame, or null if it never does. A pure touch — grazing a corner, or sitting
// on a boundary and moving away — is not a hit: it must enter (tEnter >= 0)
// with a real overlap interval (tEnter < tExit).
function sweptEntry(ball, px, py, dx, dy, brick) {
  const left = brick.x - ball.r;
  const right = brick.x + brick.w + ball.r;
  const top = brick.y - ball.r;
  const bottom = brick.y + brick.h + ball.r;

  let t0x = -Infinity;
  let t1x = Infinity;
  let t0y = -Infinity;
  let t1y = Infinity;

  if (dx !== 0) {
    if (dx > 0) {
      t0x = (left - px) / dx;
      t1x = (right - px) / dx;
    } else {
      t0x = (right - px) / dx;
      t1x = (left - px) / dx;
    }
  } else if (px < left || px > right) {
    return null; // moving parallel to the box, outside its span: never enters
  }

  if (dy !== 0) {
    if (dy > 0) {
      t0y = (top - py) / dy;
      t1y = (bottom - py) / dy;
    } else {
      t0y = (bottom - py) / dy;
      t1y = (top - py) / dy;
    }
  } else if (py < top || py > bottom) {
    return null;
  }

  const tEnter = Math.max(t0x, t0y);
  const tExit = Math.min(t1x, t1y);

  // No overlap interval, the box is behind the start, the entry is beyond the
  // end of this frame, or the segment only grazes a corner (zero-width
  // touch): no bounce.
  if (tEnter > tExit || tExit < 0 || tEnter > 1 || tEnter < 0) return null;
  if (tExit - tEnter < 1e-9) return null;
  return tEnter;
}

// Resolves one bounce against a brick at the ball's current position.
// The axis with the smaller penetration is the face that was hit: flip vy on a
// top/bottom hit, vx on a side hit, leave the other component alone; equal
// penetrations mean a diagonal hit on a corner, flip both. The ball is then

